/// True when `name` is a reserved word of `language`.
pub fn is_reserved_word(language: &Language, name: &str) -> bool {
    match language {
        Language::Vhdl => VHDL_2008.contains(&name.to_ascii_lowercase().as_str()),
        Language::SystemVerilog => SYSTEMVERILOG_2017.contains(&name),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn vhdl_reserved_words_ignore_case() {
        for name in ["bus", "BUS", "Signal", "out"] {
            assert!(is_reserved_word(&Language::Vhdl, name), "{name}");
        }
        for name in ["dbus", "logic", "wire", "clk"] {
            assert!(!is_reserved_word(&Language::Vhdl, name), "{name}");
        }
    }

    #[test]
    fn systemverilog_reserved_words_depend_on_case() {
        for name in ["logic", "wire", "output"] {
            assert!(is_reserved_word(&Language::SystemVerilog, name), "{name}");
        }
        for name in ["Logic", "bus", "signal", "clk"] {
            assert!(!is_reserved_word(&Language::SystemVerilog, name), "{name}");
        }
    }

    /// `contains` on a sorted table with no duplicate is easy to review
    /// against the standard.
    #[test]
    fn tables_are_sorted_lower_case_and_have_no_duplicate() {
        for table in [VHDL_2008, SYSTEMVERILOG_2017] {
            assert!(table.windows(2).all(|pair| pair[0] < pair[1]));
            assert!(table.iter().all(|w| *w == w.to_ascii_lowercase()));
        }
    }
}
